exercises.starterCode:
// Configuración de una cuenta de estudio recién creada. Corrige su defecto principal.
export const cuenta = {
  usuarioRaiz: {
    mfa: [],
    clavesDeAcceso: ["AKIAIOSFODNN7EXAMPLE"],
    uso: "tareas diarias de administración",
  },
  usuarioAdministrativo: null,
  contactosAlternativos: [
    { tipo: "FACTURACION", correo: "facturacion@ejemplo.com" },
    { tipo: "OPERACIONES", correo: "operaciones@ejemplo.com" },
    { tipo: "SEGURIDAD", correo: "seguridad@ejemplo.com" },
  ],
};

solution.code:
export const cuenta = {
  usuarioRaiz: {
    mfa: ["passkey"],
    clavesDeAcceso: [],
    uso: "solo tareas que exigen credenciales de raíz",
  },
  usuarioAdministrativo: {
    nombre: "admin-estudio",
    mfa: ["aplicacion-virtual"],
  },
  contactosAlternativos: [
    { tipo: "FACTURACION", correo: "facturacion@ejemplo.com" },
    { tipo: "OPERACIONES", correo: "operaciones@ejemplo.com" },
    { tipo: "SEGURIDAD", correo: "seguridad@ejemplo.com" },
  ],
};

spec.code:
const admin = cuenta.usuarioAdministrativo;
assert.ok(admin !== null, "falta el usuario administrativo");
assert.ok(Array.isArray(admin.mfa) && admin.mfa.length >= 1, "el usuario administrativo necesita MFA");

exercises.starterCode:
// Contactos alternativos de una cuenta. La lista no cumple el contrato del objeto.
export const contactos = {
  correoRaiz: "cuenta@ejemplo.com",
  tiposPermitidos: ["FACTURACION", "OPERACIONES", "SEGURIDAD"],
  contactos: [
    { tipo: "FACTURACION", correo: "facturacion@ejemplo.com" },
    { tipo: "SEGURIDAD", correo: "seguridad@ejemplo.com" },
    { tipo: "SEGURIDAD", correo: "cuenta@ejemplo.com" },
  ],
};

solution.code:
export const contactos = {
  correoRaiz: "cuenta@ejemplo.com",
  tiposPermitidos: ["FACTURACION", "OPERACIONES", "SEGURIDAD"],
  contactos: [
    { tipo: "FACTURACION", correo: "facturacion@ejemplo.com" },
    { tipo: "OPERACIONES", correo: "operaciones@ejemplo.com" },
    { tipo: "SEGURIDAD", correo: "seguridad@ejemplo.com" },
  ],
};

spec.code:
for (const contacto of contactos.contactos) {
  assert.ok(contactos.tiposPermitidos.includes(contacto.tipo), contacto.tipo + " no es un tipo permitido");
}

for (const contacto of contactos.contactos) {
  assert.notStrictEqual(contacto.correo, contactos.correoRaiz, "el correo de la raíz no es un contacto alternativo");
}
